{
    vec3 noData;
    vec3 defaultValue;
    vec3 minValue;
    vec3 maxValue;
};
struct Metadata
{
    float temperature;
    vec3 tint;
};
struct MetadataClass
{
    floatMetadataClass temperature;
    vec3MetadataClass tint;
};
struct MetadataStatistics
{
    float _empty;
};
void initializeMetadata(FeatureIds featureIds, out Metadata metadata, out MetadataClass metadataClass, out MetadataStatistics metadataStatistics, ProcessedAttributes attributes)
{
    metadata.temperature = czm_valueTransform(u_temperature_offset, u_temperature_scale, attributes.temp);
    metadataClass.temperature.noData = float(-1);
    metadataClass.temperature.defaultValue = float(0);
    metadataClass.temperature.minValue = float(-20);
    metadataClass.temperature.maxValue = float(80);
    metadata.tint = attributes.tint;
    metadataClass.tint.minValue = vec3(0,0,0);
    metadataClass.tint.maxValue = vec3(255,255,255);
}
void setMetadataVaryings()
