fragment.source:
uniform sampler2D u_propertyTexture_0;
uniform mat3 u_propertyTexture_0Transform;
uniform float u_temperature_offset;
uniform float u_temperature_scale;
uniform sampler2D u_propertyTexture_1;
struct floatMetadataClass
{
    float noData;
    float defaultValue;
    float minValue;
    float maxValue;
};
struct uintMetadataClass
{
    uint noData;
    uint defaultValue;
    uint minValue;
    uint maxValue;
};
struct vec3MetadataClass
{
    vec3 noData;
    vec3 defaultValue;
    vec3 minValue;
    vec3 maxValue;
};
struct Metadata
{
    float temperature;
    uint code;
    vec3 tint;
};
struct MetadataClass
{
    floatMetadataClass temperature;
    uintMetadataClass code;
    vec3MetadataClass tint;
};
struct MetadataStatistics
{
    float _empty;
};
void initializeMetadata(FeatureIds featureIds, out Metadata metadata, out MetadataClass metadataClass, out MetadataStatistics metadataStatistics, ProcessedAttributes attributes)
{
    metadata.temperature = czm_valueTransform(u_temperature_offset, u_temperature_scale, int(255.0 * texture(u_propertyTexture_0, vec2(u_propertyTexture_0Transform * vec3(attributes.texCoord_1, 1.0))).rgba));
    metadataClass.temperature.noData = float(-1);
    metadataClass.temperature.defaultValue = float(0);
    metadataClass.temperature.minValue = float(-20);
    metadataClass.temperature.maxValue = float(80);
    metadata.code = int(255.0 * texture(u_propertyTexture_1, attributes.texCoord_0).r);
    metadataClass.code.noData = uint(255);
    metadataClass.code.defaultValue = uint(1);
    metadata.tint = texture(u_propertyTexture_1, attributes.texCoord_0).rgb;
    metadataClass.tint.minValue = vec3(0,0,0);
    metadataClass.tint.maxValue = vec3(255,255,255);
}
void metadataStage(
  FeatureIds featureIds,
  out Metadata metadata,
  out MetadataClass metadataClass,
  out MetadataStatistics metadataStatistics,
  ProcessedAttributes attributes
  )
{
  initializeMetadata(featureIds, metadata, metadataClass, metadataStatistics, attributes);
}

